// minerpg: the Side Class talent tab's unlock rules (pack 1.7.0). The 9-point gate is in
// server_scripts/minerpg_side_class.js.
// Design: docs/superpowers/specs/2026-11-08-minerpg-side-class-design.md. The tab itself (Pufferfish category
// minerpg:side_skills) is generated by pack/tools/gen_side_class.py, which also writes kubejs/side_class/rules.json.
//
// What the data can't express (this file):
// - the side class is never the main class, both ways: a side root of the main class is refused, and so is a main
//   root of the side class (someone who resets the main tree and picks their side class);
// - at most 2 of a class's 4 side spells: a third is refused (locking it refunds the point and drops its spell).

const $SCSkillsAPI = Java.loadClass('net.puffish.skillsmod.api.SkillsAPI')
const $SCResourceLocation = Java.loadClass('net.minecraft.resources.ResourceLocation')
const $SCComponent = Java.loadClass('net.minecraft.network.chat.Component')
const $SCFormat = Java.loadClass('net.minecraft.ChatFormatting')

const SC_MAIN_ID = 'skill_tree_rpgs:class_skills'
const SC_SIDE_ID = 'minerpg:side_skills'
const SC_MAX_SPELLS = 2
const SC_RULES = JsonIO.read('kubejs/side_class/rules.json')

// class -> its 4 side spell skill ids; side spell skill id -> class; main/side root skill id -> class.
var scSpellsByClass = {}
var scSpellClass = {}
var scMainRoots = {}
var scSideRoots = {}
if (SC_RULES == null) {
  console.error('[minerpg] side class: kubejs/side_class/rules.json is missing')
} else {
  for (var cls in SC_RULES.spells) {
    scSpellsByClass[cls] = []
    SC_RULES.spells[cls].forEach(id => {
      scSpellsByClass[cls].push(String(id))
      scSpellClass[String(id)] = String(cls)
    })
  }
  for (var mainId in SC_RULES.main_roots) scMainRoots[String(mainId)] = String(SC_RULES.main_roots[mainId])
  for (var sideId in SC_RULES.side_roots) scSideRoots[String(sideId)] = String(SC_RULES.side_roots[sideId])
}

function scCategory(id) {
  var category = $SCSkillsAPI.getCategory($SCResourceLocation.parse(id))
  return category.isPresent() ? category.get() : null
}

// The class whose root the player has unlocked in a category (each tab has one root), or null.
function scRootClass(category, player, roots) {
  var found = null
  category.streamUnlockedSkills(player).forEach(skill => {
    var cls = roots[String(skill.getId())]
    if (cls) found = cls
  })
  return found
}

function scRefuse(player, category, skillId, message) {
  category.getSkill(skillId).get().lock(player)
  // withStyle is overloaded (formatting / style / operator); Rhino needs the one named.
  player.sendSystemMessage($SCComponent.literal(message)['withStyle(net.minecraft.ChatFormatting)']($SCFormat.GOLD))
}

// A startup script: Pufferfish keeps its listeners for the whole run, and server scripts run again on every reload
// (and can't keep state in KubeJS' global), so registering there would add a listener per reload. Changes here need a
// restart, not /reload.
function scOnUnlock(player, categoryId, skillId) {
  var main = scCategory(SC_MAIN_ID)
  var side = scCategory(SC_SIDE_ID)
  if (main == null || side == null) return
  var category = String(categoryId)
  var id = String(skillId)
  if (category == SC_SIDE_ID && scSideRoots[id]) {
    if (scSideRoots[id] == scRootClass(main, player, scMainRoots)) {
      scRefuse(player, side, id, 'Your side class has to be a different class from your main class.')
    }
  } else if (category == SC_MAIN_ID && scMainRoots[id]) {
    if (scMainRoots[id] == scRootClass(side, player, scSideRoots)) {
      scRefuse(player, main, id, 'That is your side class. Reset it with an Orb of Oblivion to make it your main class.')
    }
  } else if (category == SC_SIDE_ID && scSpellClass[id]) {
    var owned = 0
    scSpellsByClass[scSpellClass[id]].forEach(spell => {
      if (String(side.getSkill(spell).get().getState(player)) == 'UNLOCKED') owned++
    })
    if (owned > SC_MAX_SPELLS) {
      scRefuse(player, side, id, 'Two side-class spells is the limit. Use an Orb of Oblivion to choose again.')
    }
  }
}

$SCSkillsAPI.registerSkillUnlockEvent((player, categoryId, skillId) => scOnUnlock(player, categoryId, skillId))
